import original from '../fixtures/startup-historical-old.json';
import { inspect, resume } from '../../tools/memory/forecast-rehearsal-entry';
interface Proof { root: object; savedAt: number; resumedAt?: number; readOnly?: boolean; recoveredThrough?: number; through?: number; status?: string; operationalIsolated?: boolean }
interface ProbeMemory extends Memory { startupHistoricalMigration?: Proof }
/** Exact fixture generated by committed ee26176 owner modules; model clocks remain1/2. */
export function probeStartupHistoricalMigration(): void {
  const memory = Memory as ProbeMemory, operational = JSON.stringify(Memory.eldrift);
  if (Game.time === 149) {
    memory.startupHistoricalMigration = { root: JSON.parse(JSON.stringify(original)),savedAt: Game.time };
    return;
  }
  const proof = memory.startupHistoricalMigration;
  if (!proof) throw new Error('Missing authentic historical records');
  const before = JSON.stringify(proof.root), recovered = inspect(proof.root);
  proof.readOnly = JSON.stringify(proof.root) === before;
  const checkpoint = recovered[0]!.planning.job?.checkpoint;
  if (!checkpoint) throw new Error('Missing historical partial progress');
  proof.recoveredThrough = checkpoint.tick;
  const result = resume(proof.root);
  if (result.status !== 'complete') throw new Error('Historical native resume did not complete');
  Object.assign(proof,{ resumedAt: Game.time,status: result.status,through: result.through,operationalIsolated: operational === JSON.stringify(Memory.eldrift) });
}
